#include <cctype>
#include <iostream>
#include <sstream>

#include "Input.h"

std::string trim(const std::string& text) {
    const char* whitespace = " \t\r\n";
    std::size_t first = text.find_first_not_of(whitespace);
    if (first == std::string::npos) {
        return "";
    }
    std::size_t last = text.find_last_not_of(whitespace);
    return text.substr(first, last - first + 1);
}

std::string toLowerCopy(std::string text) {
    for (char& c : text) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    return text;
}

std::vector<bool> parseKeepers(const std::string& line, std::size_t count) {
    std::vector<bool> kept(count, false);
    std::string cleaned = toLowerCopy(trim(line));

    if (cleaned == "a") {
        kept.assign(count, true);
        return kept;
    }

    std::stringstream numbers(cleaned);
    int number = 0;
    while (numbers >> number) {
        if (number >= 1 && static_cast<std::size_t>(number) <= count) {
            kept[static_cast<std::size_t>(number) - 1] = true;
        }
    }
    return kept;
}

bool parseInt(const std::string& line, int& value) {
    std::stringstream numbers(trim(line));
    int parsed = 0;
    char extra = 0;
    if (!(numbers >> parsed)) {
        return false;
    }
    if (numbers >> extra) {
        return false;
    }
    value = parsed;
    return true;
}

bool readLine(std::string& line) {
    return static_cast<bool>(std::getline(std::cin, line));
}

bool askInt(const std::string& prompt, int low, int high, int& value) {
    while (true) {
        std::cout << prompt;
        std::string line;
        if (!readLine(line)) {
            return false;
        }
        int parsed = 0;
        if (parseInt(line, parsed) && parsed >= low && parsed <= high) {
            value = parsed;
            return true;
        }
        std::cout << "Please type a whole number from " << low << " to " << high << ".\n";
    }
}

bool parseYesNo(const std::string& line, bool& yes) {
    std::string cleaned = toLowerCopy(trim(line));
    if (cleaned == "y" || cleaned == "yes") { yes = true; return true; }
    if (cleaned == "n" || cleaned == "no") { yes = false; return true; }
    return false;
}

bool askYesNo(const std::string& prompt, bool& yes) {
    while (true) {
        std::cout << prompt;
        std::string line;
        if (!readLine(line)) return false;
        if (parseYesNo(line, yes)) return true;
        std::cout << "Please type y or n.\n";
    }
}

